import numpy as np

r = 1.73737
N = 2025

# Check powers of r near 2025
powers = {}
for i in range(1, 20):
    val = r**i
    powers[i] = val

print("Powers of r:")
for i in range(1, 20):
    print(f"r^{i} = {powers[i]:.2f}")

# Find the largest power m such that r^m <= 2025
m = 0
for i in range(20):
    if powers[i] <= N:
        m = i
    else:
        break

print(f"\nLargest power m such that r^m <= 2025 is m = {m}")
print(f"r^{m} = {powers[m]:.2f}")
